proguardAdditions.insert:

-keep class com.taptap.sdk.review.** { *; }
-keep interface com.taptap.sdk.review.** { *; }
-keep class com.taptap.sdk.review.unity.** { *; }
-keepclassmembers class com.taptap.sdk.review.unity.** { *; }
-keepclasseswithmembernames class * { native <methods>; }
-keep class com.taptap.sdk.kit.internal.enginebridge.EngineBridge { *; }
-keepclassmembers class com.taptap.sdk.kit.internal.enginebridge.EngineBridge {
    public static final com.taptap.sdk.kit.internal.enginebridge.EngineBridge INSTANCE;
    public void init(android.app.Activity);
    public void registerService(java.lang.Class, com.taptap.sdk.kit.internal.enginebridge.IEngineBridgeService);
    public void execCommand(java.lang.String, com.taptap.sdk.kit.internal.enginebridge.EngineBridgeCallback);
}
-keep interface com.taptap.sdk.kit.internal.enginebridge.IEngineBridgeService { *; }

gameActivityOnCreateAdditions.insert:

try {
    EngineBridge.INSTANCE.init(this);
    EngineBridge.INSTANCE.registerService(
        BridgeReviewService.class, new BridgeReviewServiceImpl());
    android.util.Log.i("TapSDK_UE", "TapReview: BridgeReviewService registered");
} catch (Exception e) {
    android.util.Log.e("TapSDK_UE", "TapReview: registerService failed: " + e.getMessage(), e);
}

gameActivityClassAdditions.insert:

public void routeToTapReview(String commandJson) {
    try {
        EngineBridge.INSTANCE.init(this);
        EngineBridge.INSTANCE.execCommand(commandJson, null);
    } catch (Exception e) {
        android.util.Log.e("TapSDK_UE", "TapReview route error: " + e.getMessage(), e);
    }
}
